float Base(float V[], float W[], int N)
{
  float sum = 0;
  for (int i=0; i<N; i++) {
    sum = sum + V[i] + W[i];
  }
  return sum;
}

void revcopy(float V[], float W[], int N)
{
  for (int i=0; i<N; i++)
    W[i] = V[N-1-i];
}

float sum3(float V[], int N)
{
  float sum = 0;
  for (int i=0; i<N; i++)
    sum = sum + V[3*i];
  return sum;
}

// A: 8×8 floats stored by rows
void mv(float A[8][8], float X[8], float Y[8])
{
  for (int i=0; i<8; i++) {   // Rep: one call per row
    float s = 0;
    for (int j=0; j<8; j++)
      s = s + A[i][j] * X[j];
    Y[i] = s;
  }
}

// A: 8×8 floats stored by columns: A[j][i] is the element (i, j)
void mv(float A[8][8], float X[8], float Y[8])
{
  for (int i=0; i<8; i++) {   // Rep: one call per row
    float s = 0;
    for (int j=0; j<8; j++)
      s = s + A[j][i] * X[j];
    Y[i] = s;
  }
}
